  `dept_belong_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_datetime` datetime(6) DEFAULT NULL,
  `create_datetime` datetime(6) DEFAULT NULL,
  `session_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `session_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `session_id` bigint DEFAULT NULL,
  `question` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `answer` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quality` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `feedback` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `vector_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` longtext COLLATE utf8mb4_unicode_ci,
  `agent_id` bigint NOT NULL,
  `creator_id` bigint DEFAULT NULL,
  `embedding_model_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_ck_creator_agent_qhash` (`creator_id`,`agent_id`,`question_hash`),
  KEY `dvadmin_agent_chat_knowledge_item_agent_id_296c409f` (`agent_id`),
  KEY `dvadmin_agent_chat_knowledge_item_creator_id_aad343e1` (`creator_id`),
  KEY `dvadmin_agent_chat_knowledge_item_embedding_model_id_fe867be0` (`embedding_model_id`),
  KEY `idx_ck_agent_creator_status` (`agent_id`,`creator_id`,`status`),
  KEY `idx_ck_creator_agent_quality` (`creator_id`,`agent_id`,`status`,`quality`),
  KEY `idx_ck_vector` (`vector_id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

