--
-- Table structure for table `dvadmin_agent_config`
--

DROP TABLE IF EXISTS `dvadmin_agent_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dvadmin_agent_config` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `modifier` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dept_belong_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_datetime` datetime(6) DEFAULT NULL,
  `create_datetime` datetime(6) DEFAULT NULL,
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `icon` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `knowledge_base` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `prompt` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `memory_enabled` tinyint(1) NOT NULL,
  `memory_window` int NOT NULL,
  `status` tinyint(1) NOT NULL,
  `creator_id` bigint DEFAULT NULL,
  `model_id` bigint DEFAULT NULL,
  `execution_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `long_term_memory` tinyint(1) NOT NULL,
  `short_term_memory` tinyint(1) NOT NULL,
  `knowledge_base_ref_id` bigint DEFAULT NULL,
  `tools_enabled` tinyint(1) NOT NULL,
  `enabled_tools` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `chat_knowledge_enabled` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  KEY `dvadmin_agent_config_creator_id_8161a50a` (`creator_id`),
  KEY `dvadmin_agent_config_model_id_a449bf6c` (`model_id`),
  KEY `dvadmin_agent_config_knowledge_base_ref_id_ffb31e39` (`knowledge_base_ref_id`)
