LL,4),(10,NULL,NULL,'2026-08-07 14:26:25.786286','2026-08-07 14:26:25.786286','playwright','Playwright MCP','浏览器自动化','浏览器自动化、网页访问、点击与截图。',5,'https://github.com/microsoft/playwright-mcp','','npx','[\"-y\", \"@playwright/mcp@latest\"]','{}','node','stdio','catalog',1,0,'需要 Node.js 18+，首次运行 npx 会自动下载。','[]',NULL,'',NULL,NULL),(11,NULL,NULL,'2026-08-07 14:26:25.792356','2026-08-07 14:26:25.792356','mysql','MySQL MCP','数据库','MySQL 只读查询、Schema 检查与表结构分析。',5,'https://github.com/benborla/mcp-server-mysql','','npx','[\"-y\", \"@benborla/mcp-server-mysql\"]','{\"MYSQL_HOST\": \"{{MYSQL_HOST}}\", \"MYSQL_PORT\": \"{{MYSQL_PORT}}\", \"MYSQL_USER\": \"{{MYSQL_USER}}\", \"MYSQL_PASS\": \"{{MYSQL_PASS}}\", \"MYSQL_DB\": \"{{MYSQL_DB}}\"}','node','stdio','catalog',1,0,'配置 MySQL 连接信息后通过 npx 本地运行。','[{\"key\": \"MYSQL_HOST\", \"label\": \"数据库地址\", \"type\": \"text\", \"required\": true, \"placeholder\": \"127.0.0.1\"}, {\"key\": \"MYSQL_PORT\", \"label\": \"端口\", \"type\": \"text\", \"required\": false, \"placeholder\": \"3306\"}, {\"key\": \"MYSQL_USER\", \"label\": \"用户名\", \"type\": \"text\", \"required\": true, \"placeholder\": \"root\"}, {\"key\": \"MYSQL_PASS\", \"label\": \"密码\", \"type\": \"password\", \"required\": true, \"placeholder\": \"\"}, {\"key\": \"MYSQL_DB\", \"label\": \"数据库名\", \"type\": \"text\", \"required\": false, \"placeholder\": \"interview\"}]',NULL,'',NULL,NULL),(12,NULL,NULL,'2026-08-07 14:26:25.798372','2026-08-07 14:26:25.798372','redis','Redis MCP','缓存数据库','Redis key-value 数据查询与维护。',4,'https://github.com/modelcontextprotocol/servers-archived','','npx','[\"-y\", \"@modelcontextprotocol/server-redis\", \"{{REDIS_URL}}\"]','{}','node','stdio','catalog',1,0,'填写 Redis 连接串，如 redis://127.0.0.1:6379。','[{\"key\": \"REDIS_URL\", \"label\": \"Redis 连接串\", \"type\": \"text\", \"required\": true, \"placeholder\": \"redis://127.0.0.1:6379\"}]',NULL,'',NULL,NULL),(13,NULL,NULL,'2026-08-07 14:26:25.805074','2026-08-07 14:26:25.805074','web_search','Web Search MCP','搜索','Web/新闻搜索，需要 Brave Search API Key。',4,'https://github.com/modelcontextprotocol/servers-archived','','npx','[\"-y\", \"@modelcontextprotocol/server-brave-search\"]','{\"BRAVE_API_KEY\": \"{{BRAVE_API_KEY}}\"}','node','stdio','catalog',1,0,'注册 Brave Search 并配置 BRAVE_API_KEY。','[{\"key\": \"BRAVE_API_KEY\", \"label\": \"Brave API Key\", \"type\": \"password\", \"required\": true, \"placeholder\": \"\"}]',NULL,'',NULL,NULL),(14,NULL,NULL,'2026-08-07 14:26:25.810076','2026-08-07 14:26:25.810076','doc_office','PDF/Office MCP','文档处理','PDF、Word、Excel、PPT 等文档转 Markdown 与内容提取。',4,'https://github.com/microsoft/markitdown','','uvx','[\"markitdown-mcp\"]','{}','uvx','stdio','catalog',1,0,'基于 MarkItDown，本地转换 Office 与 PDF 文档。','[]',NULL,'',NULL,NULL),(15,NULL,NULL,'2026-08-07 14:26:25.816074','2026-08-07 14:26:25.816074','docker','Docker MCP','容器运维','容器、镜像、网络与 Docker 环境管理。',4,'https://github.com/hypnosis/docker-mcp-server','','npx','[\"-y\", \"@hypnosis/docker-mcp-server\"]','{}','node','stdio','catalog',1,0,'需要本地 Docker CLI 可用。','[]',NULL,'',NULL,NULL),(16,NULL,NULL,'2026-08-07 14:26:25.820514','2026-08-07 14:26:25.820514','excel','Excel MCP','表格处理','Excel 文件读写、公式与工作表管理。',4,'https://github.com/BACH-AI-Tools/excel-mcp-server','','uvx','[\"excel-mcp-server\", \"stdio\"]','{}','uvx','stdio','catalog',1,0,'示例：uvx excel-mcp-server stdio','[]',NULL,'',NULL,NULL),(17,NULL,NULL,'2026-08-07 14:26:25.825515','2026-08-07 14:26:25.825515','gitee','Gitee MCP','代码托管','Gitee 仓库、Issue、PR 与文件操作。',3,'https://github.com/oschina/mcp-gitee','','go','[\"run\", \"gitee.com/oschina/mcp-gitee@latest\", \"--transport\", \"stdio\"]','{\"GITEE_ACCESS_TOKEN\": \"{{GITEE_ACCESS_TOKEN}}\"}','go','stdio','catalog',1,0,'需要 Go 1.23+，首次运行自动拉取源码。','[{\"key\": \"GITEE_ACCESS_TOKEN\", \"label\": \"Gitee Token\", \"type\": \"password\", \"required\": true, \"placeholder\": \"\"}]',NULL,'',NULL,NULL);
