  `creator_id` bigint DEFAULT NULL,
  `session_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `dvadmin_interview_proctor_event_creator_id_7383e04b` (`creator_id`),
  KEY `dvadmin_interview_proctor_event_session_id_73369480` (`session_id`)
) ENGINE=InnoDB AUTO_INCREMENT=214 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
