CREATE TABLE `dvadmin_interview_round` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `modifier` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dept_belong_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_datetime` datetime(6) DEFAULT NULL,
  `create_datetime` datetime(6) DEFAULT NULL,
  `type_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `agent_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `agent_prompt` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_count` int NOT NULL,
  `max_questions` int NOT NULL,
  `summary` json NOT NULL,
  `agent_id` bigint DEFAULT NULL,
  `creator_id` bigint DEFAULT NULL,
  `session_id` bigint NOT NULL,
  `type_config_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `dvadmin_interview_round_agent_id_19b4d1bb` (`agent_id`),
  KEY `dvadmin_interview_round_creator_id_7cac231a` (`creator_id`),
  KEY `dvadmin_interview_round_session_id_53bbc862` (`session_id`),
  KEY `dvadmin_interview_round_type_config_id_e9ca1522` (`type_config_id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
