INSERT INTO `dvadmin_resume` VALUES (1,NULL,NULL,NULL,'2026-08-10 08:53:09.280268','2026-08-10 08:53:09.280268','陈波-运维工程师','modern','{}','zh','{}','draft',1),(2,NULL,'1043',NULL,'2026-08-10 14:56:25.417361','2026-08-10 09:06:52.842629','刘佳帅-运维简历','ribbon','{\"font_family\": \"\'Microsoft YaHei\', sans-serif\"}','zh','{\"skills\": [{\"name\": \"Python 后端开发\", \"skills\": [\"熟练使用 Python 进行业务应用开发；熟悉 Python3.12 环境配置；掌握 Django\", \"FlaskWeb 框架；熟练 SQLite\", \"Redis 数据库；能够编写自动化部署脚本\", \"批量处理脚本；熟悉接口调试\", \"后端故障排查。\"]}, {\"name\": \"服务器、容器与运维\", \"skills\": [\"熟练 CentOS Linux 操作系统；Nginx 反向代理\", \"uWSGI 服务配置；Docker 容器部署调试；EasyTier 内网环境；熟悉项目环境依赖报错排查\", \"服务性能优化。\"]}, {\"name\": \"前端 & BI 可视化工具\", \"skills\": [\"能够使用 Streamlit 快速搭建 AI 可视化应用；熟练 DataEase 等 BI 数据分析平台；掌握基础前端调试；可完成数据分析平台整体搭建。\"]}, {\"name\": \"软技能 & 行业专项技能\", \"skills\": [\"具备高校产教融合实训项目落地经验；可独立设计 AI 人才培养课程体系\", \"编写实训教材；拥有项目进度管控\", \"团队任务分配\", \"招投标方案编写经验；熟悉开源框架\", \"软件安全等保基础规范\", \"开源许可证常识。\"]}], \"projects\": [{\"name\": \"星辰零售集团AI智能数据分析平台\", \"endDate\": \"2026-01\", \"startDate\": \"2024-10\", \"highlights\": [\"完成整套数据分析平台环境搭建与容器化部署\", \"集成DataEase、Streamlit可视化BI工具\", \"产出多套商用级AI数据分析实训案例\", \"负责项目全周期进度管控与问题攻关\"], \"description\": \"担任项目负责人，统筹平台后端架构、BI可视化模块开发、Docker容器环境部署；负责需求梳理、开发人员任务分配、线上故障排查；面向高校实训场景封装数据分析实训案例，编写实训指导文档，用于学生大数据、AI数据分析实操教学。\\n\"}, {\"name\": \"基于YOLO‑v8手势识别AI实训平台\", \"endDate\": \"2026-08\", \"startDate\": \"2026-02\", \"highlights\": [\"熟练完成CentOS服务器全套运维配置\", \"搭建可交付的深度学习实训环境\", \"定制视觉方向实训课程\", \"处理模型部署过程中的各类依赖报错\"], \"description\": \"主导计算机视觉实训项目建设，完成Python3.12实训环境配置、模型训练调试、Nginx服务部署；设计课程实操流程，面向高校学员开展手势检测、目标识别相关实训授课，解决模型推理、数据集处理等常见技术问题。\\n\"}], \"education\": [{\"degree\": \"大学本科\", \"endDate\": \"2024-07\", \"startDate\": \"2022-09\", \"highlights\": [\"数据结构与算法、python程序设计开发、java程序设计开发、网页设计开发、数据库管理\"], \"description\": \"软件工程专业\", \"institution\": \"延安大学\"}], \"personalInfo\": {\"email\": \"liujs@demo.com\", \"phone\": \"16858889994\", \"github\": \"无\", \"wechat\": \"16858889994\", \"fullName\": \"刘佳帅\", \"jobTitle\": \"运维工程师\", \"location\": \"陕西西安\"}, \"workExperience\": [{\"company\": \"西安鸥鹏互联科技有限公司\", \"endDate\": \"2026-06\", \"position\": \"项目经理\", \"startDate\": \"2024-08\", \"highlights\": [\"独立负责多所高校AI产教融合实训项目落地\", \"搭建132‑134天分层次AI人才培养课程体系\", \"完成YOLOv8计算机视觉实训平台研发调试\", \"熟练掌握Linux环境、容器部署、后端环境运维\", \"可独立编写投标方案、课程教材以及实训手册\"], \"description\": \"1、负责高校AI方向产教融合全流程项目管理，包含招投标方案编撰、合规审核、实训课程体系搭建；\\n2、统筹YOLO‑v8手势识别、数据分析平台等AI实训项目落地，负责实训环境部署、技术调试、教学资源开发；\\n3、对接合作院校师生，把控实训授课、项目答疑、实训验收全流程；\\n4、管理后端、前端、运维技术人员，规划开发任务，排查Linux、Docker、Redis等环境故障；\\n5、搭建AI复合型人才培养架构，编写教材、实训指导文档，迭代课程方案。\"}]}','ai_passed',1043),(3,NULL,'1043',NULL,'2026-08-10 14:27:16.278719','2026-08-10 14:24:06.356848','刘佳帅-python工程师','classic','{}','zh','{}','draft',1043),(6,NULL,'1049',NULL,'2026-08-21 16:33:41.745859','2026-08-21 15:24:36.481035','网络工程师','modern','{}','zh','{\"skills\": [{\"name\": \"网络\", \"skills\": [\"熟悉TCP/IP协议栈，掌握VLAN\", \"STP\", \"OSPF\", \"静态路由等常用网络技术，具备中大型企业局域网及广域网的规划\", \"配置与排障能力。\"]}, {\"name\": \"路由器\", \"skills\": [\"熟练配置Cisco/H3C/Huawei等主流品牌的路由器\", \"交换机，了解防火墙\", \"VPN\", \"ACL\", \"NAT等安全策略的部署与维护。\"]}, {\"name\": \"数据处理\", \"skills\": [\"掌握Wireshark\", \"Zabbix等网络抓包与监控工具，能通过流量分析和日志快速定位网络异常与性能瓶颈。\"]}, {\"name\": \"服务器\", \"skills\": [\"了解Windows Server\", \"Linux（CentOS/Ubuntu）系统基本操作，可完成常见的网络服务配置与维护。\"]}, {\"name\": \"机房\", \"skills\": [\"熟悉机房基础设施的日常巡检与维护，包括服务器\", \"交换机\", \"UPS\", \"精密空调等设备的运行监控。\"]}, {\"name\": \"专业文档\", \"skills\": [\"具备良好的技术文档编写能力和跨部门沟通能力，曾输出多份网络运维手册和故障处理报告。\"]}], \"projects\": [], \"languages\": [], \"personalInfo\": {\"email\": \"lichunfeng@demo.com\", \"phone\": \"16800010001\", \"wechat\": \"lichunfeng\", \"fullName\": \"李淳风\", \"jobTitle\": \"网络工程师\", \"location\": \"陕西西安\"}, \"certifications\": [], \"workExperience\": [{\"company\": \"XX信息科技公司\", \"endDate\": \"2019-06\", \"position\": \"网络运维工程师（实习）\", \"startDate\": \"2018-07\", \"highlights\": [], \"description\": \"协助工程师完成办公区300余台终端的网络接入配置与故障排除，日均处理工单10-15单，解决率达95%。\\n参与公司机房服务器、交换机、UPS等设备的日常巡检，记录并上报潜在风险，保障核心设备稳定运行。\"}]}','draft',1049);
