补贴、培训学习基金及定期技术分享内部分享会。\\n- 配备 MacBook Pro 或同等级开发设备，另有餐补、下午茶及团建活动。\', \'job_title\': \'python工程师\', \'resume\': 2, \'selected_types\': [\'scenario\']}','POST',NULL,'127.0.0.1','Edge 151.0.0','2000','Windows 10','{\'code\': 2000, \'msg\': \'创建成功\'}',1,1043),(226,NULL,NULL,NULL,'2026-08-10 10:31:52.907559','2026-08-10 10:31:52.907559','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(227,NULL,NULL,NULL,'2026-08-10 10:31:59.234856','2026-08-10 10:31:58.504679','','/api/token/','{\'password\': \'**********\', \'username\': \'stu_2021_ljs_sc\'}','POST',NULL,'127.0.0.1','Other','2000','Windows 10','{\'code\': 2000, \'msg\': \'请求成功\'}',1,NULL),(228,NULL,NULL,NULL,'2026-08-10 10:32:15.143958','2026-08-10 10:32:14.418904','','/api/token/','{\'password\': \'**********\', \'username\': \'stu_2021_ljs_sc\'}','POST',NULL,'127.0.0.1','Other','2000','Windows 10','{\'code\': 2000, \'msg\': \'请求成功\'}',1,NULL),(229,NULL,NULL,NULL,'2026-08-10 10:32:18.209334','2026-08-10 10:32:18.209334','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(230,NULL,NULL,NULL,'2026-08-10 10:32:56.216110','2026-08-10 10:32:56.216110','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(231,NULL,NULL,NULL,'2026-08-10 10:33:22.616495','2026-08-10 10:33:22.616495','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(232,NULL,NULL,NULL,'2026-08-10 10:33:57.736466','2026-08-10 10:33:57.736466','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(233,NULL,NULL,NULL,'2026-08-10 10:34:07.650040','2026-08-10 10:34:07.616465','面试会话表','/api/interview/3/control/','{\'action\': \'mark\', \'round_id\': 3, \'message_id\': 23}','POST',NULL,'127.0.0.1','Edge 151.0.0','2000','Windows 10','{\'code\': 2000, \'msg\': \'已标记\'}',1,1043),(234,NULL,NULL,NULL,'2026-08-10 10:34:20.743870','2026-08-10 10:34:20.743870','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(235,NULL,NULL,NULL,'2026-08-10 10:35:27.570788','2026-08-10 10:35:27.199784','','/api/token/','{\'username\