技术驱动，晋升通道清晰（初级→中级→高级→运维专家）。\', \'job_title\': \'初级运维工程师\', \'resume\': 2, \'selected_types\': [\'technical\']}','POST',NULL,'127.0.0.1','Edge 151.0.0','2000','Windows 10','{\'code\': 2000, \'msg\': \'创建成功\'}',1,1043),(338,NULL,NULL,NULL,'2026-08-10 13:56:22.082390','2026-08-10 13:56:22.082390','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(339,NULL,NULL,NULL,'2026-08-10 13:56:55.924056','2026-08-10 13:56:55.924056','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(340,NULL,NULL,NULL,'2026-08-10 13:57:24.038809','2026-08-10 13:57:24.038809','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(341,NULL,NULL,NULL,'2026-08-10 13:57:42.469188','2026-08-10 13:57:42.469188','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(342,NULL,NULL,NULL,'2026-08-10 13:58:05.173038','2026-08-10 13:58:05.173038','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(343,NULL,NULL,NULL,'2026-08-10 13:59:08.609708','2026-08-10 13:59:08.609708','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(344,NULL,NULL,NULL,'2026-08-10 13:59:55.402563','2026-08-10 13:59:55.402563','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(345,NULL,NULL,NULL,'2026-08-10 14:00:35.186485','2026-08-10 14:00:35.186485','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(346,NULL,NULL,NULL,'2026-08-10 14:00:46.934817','2026-08-10 14:00:46.934817','面试会话表',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL),(347,NULL,NULL,NULL,'2026-08-10 14:02:16.113279','2026-08-10 14:00:51.514891','面试会话表','/api/interview/4/report/','{}','POST',NULL,'127.0.0.1','Edge 151.0.0','2000','Windows 10','{\'code\': 2000, \'msg\': \'报告生成成功\'}',1,1043),(348,NULL,NULL,NULL,'2026-08-10 14:03:01.431781','2026-08-10 14:01:23.072381','面试会话表','/api/interview/4/report/','{}','POST',NULL,'127.0.0.1','Edge 151.0.0','4000','Windows 10','{\'code\': 4000, \'msg\': \'(1062, \"Duplicate entry \\\'4\\\' for key \\\'dvadmin_interview_report.session_id\\\'\")\'}',0,1043)