INSERT INTO `dvadmin_written_exam_report` VALUES (1,NULL,NULL,NULL,'2026-08-19 17:02:36.242039','2026-08-19 16:14:12.579892',22.8,0,'{\"essay_score\": \"0.0\", \"coding_score\": \"20.0\", \"single_score\": \"1.0\", \"multiple_score\": \"1.8\"}','[{\"score\": \"0.0\", \"title\": \"SQL 中统计分组数量的聚合函数是（　）\", \"correct\": false, \"analysis\": \"COUNT 计数，配合 GROUP BY 分组统计\", \"question_id\": 1244, \"question_type\": \"single\", \"correct_options\": [\"A\"]}, {\"score\": \"1.0\", \"title\": \"MySQL 中字符集 utf8mb4 相比 utf8 的特点是（　）\", \"correct\": true, \"analysis\": \"utf8mb4 支持 4 字节字符，兼容 emoji\", \"question_id\": 783, \"question_type\": \"single\", \"correct_options\": [\"A\"]}, {\"score\": \"0.5\", \"title\": \"弹性伸缩的触发方式包括？\", \"correct\": false, \"analysis\": \"AS 支持定时、周期、指标（如 CPU 阈值）与手动四种触发方式。\", \"question_id\": 410, \"question_type\": \"multiple\", \"correct_options\": [\"A\", \"B\", \"C\", \"D\"]}, {\"score\": \"1.3\", \"title\": \"终端防病毒与 EDR 的联动能力有（　）\", \"correct\": false, \"analysis\": \"查杀、行为隔离与取证；不应一刀切阻止外联\", \"question_id\": 1881, \"question_type\": \"multiple\", \"correct_options\": [\"A\", \"B\", \"C\"]}, {\"score\": \"0.0\", \"title\": \"简述 HPA 的工作原理。\", \"correct\": null, \"analysis\": \"HPA 是 Kubernetes 水平弹性的核心控制器。\", \"question_id\": 283, \"question_type\": \"essay\", \"correct_options\": null}, {\"score\": \"20.0\", \"title\": \"加权轮询负载均衡\\n\\n第一行输入后端数量 N，随后 N 行「名称 权重」，再输入请求次数 M；按平滑加权轮询（Smooth WRR）输出前 M 次请求选中的后端。\\n\\n输入描述：N、N 行后端、M。\\n输出描述：每行一个选中的后端名称。\", \"correct\": null, \"analysis\": \"平滑加权轮询保证分布均匀且避免突发连续选中同一后端。\", \"question_id\": 241, \"question_type\": \"coding\", \"correct_options\": null}]','[{\"count\": 21, \"event_type\": \"face_lost\"}]','笔试已结束，部分主观题自动判分失败，请教师人工复核。',NULL,1),(2,NULL,NULL,NULL,'2026-08-19 17:02:36.274555','2026-08-19 16:28:00.835583',22.3,0,'{\"essay_score\": \"0.0\", \"coding_score\": \"20.0\", \"single_score\": \"0.0\", \"multiple_score\": \"2.3\"}','[{\"score\": \"0.0\", \"title\": \"LLM 生成时 stop（停止序列）参数的作用是（　）\", \"correct\": fa