  `id` bigint NOT NULL AUTO_INCREMENT,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `modifier` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dept_belong_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_datetime` datetime(6) DEFAULT NULL,
  `create_datetime` datetime(6) DEFAULT NULL,
  `question_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `options` json NOT NULL,
  `answer` json NOT NULL,
  `score` decimal(5,1) NOT NULL,
  `analysis` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `difficulty` smallint unsigned NOT NULL,
  `tags` json NOT NULL,
  `language` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code_template` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `test_cases` json NOT NULL,
  `time_limit_ms` int NOT NULL,
  `memory_limit_mb` int NOT NULL,
